-- Run with: psql -f 002_load.sql
SET search_path TO wwidw;

\copy "City" ("City Key", "WWI City ID", "City", "State Province", "Country", "Continent", "Sales Territory", "Region", "Subregion", "Latest Recorded Population", "Valid From", "Valid To", "Lineage Key") FROM PROGRAM 'gzip -dc City.csv.gz' WITH (FORMAT csv)
\copy "Customer" ("Customer Key", "WWI Customer ID", "Customer", "Bill To Customer", "Category", "Buying Group", "Primary Contact", "Postal Code", "Valid From", "Valid To", "Lineage Key") FROM PROGRAM 'gzip -dc Customer.csv.gz' WITH (FORMAT csv)
\copy "Date" ("Date", "Day Number", "Day", "Month", "Short Month", "Calendar Month Number", "Calendar Month Label", "Calendar Year", "Calendar Year Label", "Fiscal Month Number", "Fiscal Month Label", "Fiscal Year", "Fiscal Year Label", "ISO Week Number") FROM PROGRAM 'gzip -dc Date.csv.gz' WITH (FORMAT csv)
\copy "Employee" ("Employee Key", "WWI Employee ID", "Employee", "Preferred Name", "Is Salesperson", "Valid From", "Valid To", "Lineage Key") FROM PROGRAM 'gzip -dc Employee.csv.gz' WITH (FORMAT csv)
\copy "Payment Method" ("Payment Method Key", "WWI Payment Method ID", "Payment Method", "Valid From", "Valid To", "Lineage Key") FROM PROGRAM 'gzip -dc Payment_Method.csv.gz' WITH (FORMAT csv)
\copy "Stock Item" ("Stock Item Key", "WWI Stock Item ID", "Stock Item", "Color", "Selling Package", "Buying Package", "Brand", "Size", "Lead Time Days", "Quantity Per Outer", "Is Chiller Stock", "Barcode", "Tax Rate", "Unit Price", "Recommended Retail Price", "Typical Weight Per Unit", "Valid From", "Valid To", "Lineage Key") FROM PROGRAM 'gzip -dc Stock_Item.csv.gz' WITH (FORMAT csv)
\copy "Supplier" ("Supplier Key", "WWI Supplier ID", "Supplier", "Category", "Primary Contact", "Supplier Reference", "Payment Days", "Postal Code", "Valid From", "Valid To", "Lineage Key") FROM PROGRAM 'gzip -dc Supplier.csv.gz' WITH (FORMAT csv)
\copy "Transaction Type" ("Transaction Type Key", "WWI Transaction Type ID", "Transaction Type", "Valid From", "Valid To", "Lineage Key") FROM PROGRAM 'gzip -dc Transaction_Type.csv.gz' WITH (FORMAT csv)
\copy "Movement" ("Movement Key", "Date Key", "Stock Item Key", "Customer Key", "Supplier Key", "Transaction Type Key", "WWI Stock Item Transaction ID", "WWI Invoice ID", "WWI Purchase Order ID", "Quantity", "Lineage Key") FROM PROGRAM 'gzip -dc Movement.csv.gz' WITH (FORMAT csv)
\copy "Order" ("Order Key", "City Key", "Customer Key", "Stock Item Key", "Order Date Key", "Picked Date Key", "Salesperson Key", "Picker Key", "WWI Order ID", "WWI Backorder ID", "Description", "Package", "Quantity", "Unit Price", "Tax Rate", "Total Excluding Tax", "Tax Amount", "Total Including Tax", "Lineage Key") FROM PROGRAM 'gzip -dc Order.csv.gz' WITH (FORMAT csv)
\copy "Purchase" ("Purchase Key", "Date Key", "Supplier Key", "Stock Item Key", "WWI Purchase Order ID", "Ordered Outers", "Ordered Quantity", "Received Outers", "Package", "Is Order Finalized", "Lineage Key") FROM PROGRAM 'gzip -dc Purchase.csv.gz' WITH (FORMAT csv)
\copy "Sale" ("Sale Key", "City Key", "Customer Key", "Bill To Customer Key", "Stock Item Key", "Invoice Date Key", "Delivery Date Key", "Salesperson Key", "WWI Invoice ID", "Description", "Package", "Quantity", "Unit Price", "Tax Rate", "Total Excluding Tax", "Tax Amount", "Profit", "Total Including Tax", "Total Dry Items", "Total Chiller Items", "Lineage Key") FROM PROGRAM 'gzip -dc Sale.csv.gz' WITH (FORMAT csv)
\copy "Stock Holding" ("Stock Holding Key", "Stock Item Key", "Quantity On Hand", "Bin Location", "Last Stocktake Quantity", "Last Cost Price", "Reorder Level", "Target Stock Level", "Lineage Key") FROM PROGRAM 'gzip -dc Stock_Holding.csv.gz' WITH (FORMAT csv)
\copy "Transaction" ("Transaction Key", "Date Key", "Customer Key", "Bill To Customer Key", "Supplier Key", "Transaction Type Key", "Payment Method Key", "WWI Customer Transaction ID", "WWI Supplier Transaction ID", "WWI Invoice ID", "WWI Purchase Order ID", "Supplier Invoice Number", "Total Excluding Tax", "Tax Amount", "Total Including Tax", "Outstanding Balance", "Is Finalized", "Lineage Key") FROM PROGRAM 'gzip -dc Transaction.csv.gz' WITH (FORMAT csv)
